$actual=@(Get-MayaQaWorkflowCatalog);$catalog=$actual;$expected=@($catalog|ForEach-Object WorkflowId);if($catalog.Count -ne $expected.Count){throw 'Catalog count mismatch.'};if(((@($catalog|ForEach-Object WorkflowId)|Sort-Object)-join '|') -ne (($expected|Sort-Object)-join '|')){throw 'Catalog IDs mismatch.'};foreach($entry in $catalog){if(!$entry.SupervisedExecutionRequired -or $entry.RevitLaunchByCoordinator -or $entry.RealDeploymentByCoordinator -or !$entry.DryRunSupported){throw "Unsafe capability state: $($entry.WorkflowId)"}}
